import AVFoundation
import DictationCore
import Foundation
import XCTest
@testable import Recognition

final class VocabularyAssetSmokeTests: XCTestCase {
    func testPinnedVocabularyChangesAndRemoval() async throws {
        let environment = ProcessInfo.processInfo.environment
        let root = URL(fileURLWithPath: try XCTUnwrap(environment["POPTART_VOCAB_SMOKE_PACK"]))
        let audio = URL(fileURLWithPath: try XCTUnwrap(environment["POPTART_VOCAB_SMOKE_AUDIO"]))
        let destination = URL(fileURLWithPath: try XCTUnwrap(environment["POPTART_VOCAB_SMOKE_OUTPUT"]))
        let clock = UptimeMonotonicClock()
        let recognizer = FluidAudioIncrementalRecognizer(modelLayout: .init(
            unifiedModelDirectory: root.appendingPathComponent("recognition/unified"),
            ctcModelDirectory: root.appendingPathComponent("recognition/ctc"),
            vadModelDirectory: root.appendingPathComponent("vad")), clock: clock)
        try await recognizer.prepare()
        XCTAssertTrue(recognizer.capabilities.personalVocabularyAvailable)
        var records: [[String: String]] = []
        for (fixture, term) in [("spoken-006", "MapleKrest"), ("spoken-010", "LindenHarbor")] {
            let file = try AVAudioFile(forReading: audio.appendingPathComponent(fixture + ".wav"),
                                      commonFormat: .pcmFormatFloat32, interleaved: false)
            XCTAssertEqual(file.processingFormat.sampleRate, 16_000)
            XCTAssertEqual(file.processingFormat.channelCount, 1)
            let recording = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: file.processingFormat,
                frameCapacity: AVAudioFrameCount(file.length)))
            try file.read(into: recording)
            let samples = try XCTUnwrap(recording.floatChannelData)[0]
            var transcripts: [String] = []
            for phase in ["before", "configured", "removed"] {
                let terms = phase == "configured" ? [term] : []
                try await recognizer.begin(personalVocabulary: .init(entries: terms), onPartial: { _ in })
                for start in stride(from: 0, to: Int(recording.frameLength), by: 1_600) {
                    let count = min(1_600, Int(recording.frameLength) - start)
                    let buffer = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: file.processingFormat,
                        frameCapacity: AVAudioFrameCount(count)))
                    buffer.frameLength = buffer.frameCapacity
                    try XCTUnwrap(buffer.floatChannelData)[0].update(from: samples + start, count: count)
                    try await recognizer.accept(.init(buffer: buffer, audioActivity: nil))
                    try await Task.sleep(for: .milliseconds(100))
                }
                let result = await recognizer.finish(deadline: clock.now().advanced(by: .seconds(30)))
                guard case let .final(text) = result else {
                    XCTFail("\(fixture)/\(phase) did not finalize: \(result)")
                    return
                }
                XCTAssertFalse(text.isEmpty)
                transcripts.append(text)
                records.append(["fixture": fixture, "phase": phase, "term": terms.first ?? "", "transcript": text])
                try JSONSerialization.data(withJSONObject: records, options: [.prettyPrinted, .sortedKeys])
                    .write(to: destination, options: .atomic)
            }
            XCTAssertEqual(transcripts[0], transcripts[2], "Removed vocabulary must not leak across recordings")
        }
        await recognizer.cancel()
    }
}
